<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">&#x2190;</text><text class="nav-title">&#x6761;&#x5F62;&#x7801;&#x751F;&#x6210;</text><text class="nav-icon"> </text></view></view><view class="content"><view class="input-section"><input class="text-input" v-model="barcodeData" placeholder="&#x8F93;&#x5165;&#x6570;&#x636E;" /></view><view class="format-section"><text class="section-title">&#x683C;&#x5F0F;</text><view class="format-btns"><view class="fmt-btn" v-for="f in formats" :key="f" :class="{active: format===f}" @click="format=f">{{f}}</view></view></view><view class="barcode-preview"><canvas canvas-id="barcodeCanvas" style="width:600rpx;height:200rpx;margin:0 auto;display:block"></canvas><view class="barcode-text" v-if="barcodeData">{{ barcodeData }}</view></view><view class="save-btn" @click="saveBarcode"><text>&#x4FDD;&#x5B58;&#x56FE;&#x7247;</text></view></view></view></template><script setup>import { ref, watch, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const barcodeData.value = "123456789012"
const format = ref("CODE128")
const formats = ["CODE128","CODE39","EAN-13"]
function goBack() { uni.navigateBack() }
function drawBarcode() { var ctx = uni.createCanvasContext("barcodeCanvas"); var w = 600, h = 200; ctx.setFillStyle("#ffffff"); ctx.fillRect(0, 0, w, h); if (!barcodeData.value) { ctx.draw(); return } ctx.setFillStyle("#000000"); var chars = barcodeData.value.split(""); var barWidth = w / (chars.length * 11 + 2); var x = barWidth * 10; chars.forEach(function(ch) { var code = ch.charCodeAt(0); for (var i = 0; i < 8; i++) { if (code & (1 << (7-i))) ctx.fillRect(x, 10, barWidth, h - 60); x += barWidth } x += barWidth * 3 }); ctx.draw() }
function saveBarcode() { uni.canvasToTempFilePath({ canvasId: "barcodeCanvas", success: function(res) { uni.saveImageToPhotosAlbum({ filePath: res.tempFilePath, success: function() { uni.showToast({ title: "&#x5DF2;&#x4FDD;&#x5B58;", icon: "success" }) } }) } }) }
watch([barcodeData, format], function() { drawBarcode() })
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } drawBarcode() })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#1e293b,#334155);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:44rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.input-section{background:#fff;border-radius:16rpx;padding:24rpx;margin-bottom:16rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04)}.text-input{width:100%;height:80rpx;background:#f5f7fb;border-radius:12rpx;padding:0 16rpx;font-size:28rpx;border:2rpx solid #eee}.format-section{background:#fff;border-radius:16rpx;padding:24rpx;margin-bottom:16rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04)}.section-title{font-size:28rpx;color:#333;font-weight:600;display:block;margin-bottom:16rpx}.format-btns{display:flex;gap:12rpx}.fmt-btn{flex:1;padding:16rpx;text-align:center;background:#f5f7fb;border-radius:12rpx;font-size:26rpx;color:#666}.fmt-btn.active{background:linear-gradient(135deg,#1e293b,#334155);color:#fff}.barcode-preview{background:#fff;border-radius:16rpx;padding:32rpx;margin-bottom:16rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04);text-align:center}.barcode-text{margin-top:16rpx;font-size:28rpx;font-family:monospace;color:#333}.save-btn{background:linear-gradient(135deg,#1e293b,#334155);border-radius:16rpx;padding:24rpx;text-align:center}.save-btn text{font-size:30rpx;color:#fff;font-weight:600}</style>